-- Import Hisnul Mouslim cours 3 (révision): 25 questions "Mérites du dhikr et invocations des actes quotidiens" depuis cours3.json.
-- tenant Abou Abdelwahab (qawaid.abouabdelwahab.com). Remplace le contenu de cours 3.
-- À exécuter une seule fois.

do $$ declare t uuid:='6badf254-27a3-4f69-98e3-e67caa917371'; c uuid;
begin
  select id into c from quiz_courses where tenant_id=t and subject='Hisnul Mouslim' and number=3;
  if c is null then
      values (t,'Hisnul Mouslim',3,'Mérites du dhikr et invocations des actes quotidiens',3) returning id into c;
  else
    update quiz_courses set title='Mérites du dhikr et invocations des actes quotidiens' where id=c;
    delete from quiz_questions where course_id=c;
  end if;
end $$;
